SELECT * FROM ( SELECT rownum AS rn, inner_query.* FROM ( SELECT user_no, user_id, user_name, user_phone, user_status FROM user_info
AND user_name LIKE '%' || #{params.keyword} || '%'
AND user_status = #{params.status}
ORDER BY user_no DESC ) inner_query WHERE rownum <= #{cri.pageNum} * #{cri.amount} ) WHERE rn > (#{cri.pageNum} - 1) * #{cri.amount}


SELECT *
FROM (
    SELECT rownum AS rn, inner_query.*
    FROM (
        SELECT
            vr.*,
            p.pet_breed
        FROM veterinary_res vr
        JOIN pet_info p ON vr.pet_no = p.pet_no



                AND user_name LIKE '%' || #{params.keyword} || '%'


                AND user_status = #{params.status}



        ORDER BY vr.res_no DESC  /* 최신 예약순 정렬 */
    ) inner_query
    WHERE rownum <= #{cri.pageNum} * #{cri.amount}
)
WHERE rn > (#{cri.pageNum} - 1) * #{cri.amount}


SELECT *
FROM (
    SELECT rownum AS rn, inner_query.*
    FROM (
        SELECT
            gr.*,
            p.pet_breed
        FROM grooming_res gr
        JOIN pet_info p ON gr.pet_no = p.pet_no



                AND user_name LIKE '%' || #{params.keyword} || '%'


                AND user_status = #{params.status}



        ORDER BY gr.res_no DESC  /* 최신 예약순 정렬 */
    ) inner_query
    WHERE rownum <= #{cri.pageNum} * #{cri.amount}
)
WHERE rn > (#{cri.pageNum} - 1) * #{cri.amount}

